from astropy.coordinates import Angle

# Example 1: Seconds just below half a unit
try:
    result1 = Angle("1d2m59.49999s").to_string(precision=0)
    probe('Angle("1d2m59.49999s").to_string(precision=0)', result1)
except Exception as e:
    probe('Angle("1d2m59.49999s").to_string(precision=0)', "__error__: " + type(e).__name__ + ": " + str(e))

# Expected value for example 1
try:
    expected1 = "1d02m59s"
    probe('expected::Angle("1d2m59.49999s").to_string(precision=0)', expected1)
except Exception as e:
    probe('expected::Angle("1d2m59.49999s").to_string(precision=0)', "__error__: " + type(e).__name__ + ": " + str(e))

# Example 2: Double rounding issue
try:
    result2 = Angle("285d29m41.76s").to_string(fields=1)
    probe('Angle("285d29m41.76s").to_string(fields=1)', result2)
except Exception as e:
    probe('Angle("285d29m41.76s").to_string(fields=1)', "__error__: " + type(e).__name__ + ": " + str(e))

# Expected value for example 2
try:
    expected2 = "285d"
    probe('expected::Angle("285d29m41.76s").to_string(fields=1)', expected2)
except Exception as e:
    probe('expected::Angle("285d29m41.76s").to_string(fields=1)', "__error__: " + type(e).__name__ + ": " + str(e))

